   (Sysutil.add_to_path path fn,acc)
| s ->

     Termcode.pp_sum_shape_version s.shapes.shape_version;
  (* just to keep the old_provers somewhere *)
  let old_provers =
    List.fold_left (load_file s) Mint.empty xml.Xml.elements
